"""
splash_screen.py -- a simple, standalone startup splash for the backup app.

Design goals:
    * Self-contained: all splash logic AND the splash image live in this one
      file. Nothing needs to be shipped, saved, or resolved as an image file in
      the script directory or the compiled bundle -- the picture is embedded
      below as a base64 JPEG and decoded straight into a QPixmap at runtime.
    * Minimal footprint in the app: it takes just an import plus one call.
    * PySide6 (same binding as the app), so there's one QApplication, one
      process, no toolkit clash.
    * The image actually stays visible for the full duration -- the wait pumps
      the Qt event loop instead of time.sleep()'ing (a blocking sleep is why a
      naive splash only flashes for a fraction of a second).

Typical use, inside the app's main(), right after QApplication is created:

    from splash_screen import show_splash
    ...
    app = QApplication(sys.argv)
    show_splash(app, seconds=3.0)   # <-- the only added call
    win = MainWindow(cfg)
    win.show()

That's it. show_splash() blocks (while keeping the splash painted and the event
loop alive) for `seconds`, then closes the splash and returns. The app then
builds and shows its window as normal.

Because the image is embedded, this is fully PyInstaller-safe with no --add-data
needed for the splash. You can still override it with an on-disk file by passing
image_name=... to show_splash(); if that file exists it wins, otherwise the
embedded image is used.
"""

import os
import sys
import time
import base64

from PySide6 import QtWidgets, QtGui, QtCore


