def _resource_path(name: str) -> str:
    """Absolute path to a bundled resource, working for both source runs and
    PyInstaller onefile builds (where files live under sys._MEIPASS). Only used
    for the optional on-disk override now that the default image is embedded."""
    base = getattr(sys, "_MEIPASS", None)
    if not base:
        base = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base, name)


def _embedded_pixmap() -> QtGui.QPixmap:
    """Decode the embedded base64 JPEG into a QPixmap. Returns a null pixmap on
    any failure (the caller then falls back to the text card)."""
    try:
        data = base64.b64decode("".join(_SPLASH_IMAGE_B64.split()))
        pix = QtGui.QPixmap()
        pix.loadFromData(data)  # Qt sniffs the format (JPEG) from the bytes.
        return pix
    except Exception:
        return QtGui.QPixmap()


def _load_pixmap(image_name: str, fallback_text: str) -> QtGui.QPixmap:
    """Get the splash pixmap. Order of preference:
      1. An on-disk file named `image_name`, if it exists (lets you override the
         embedded art without editing this file).
      2. The embedded base64 image.
      3. A plain text card, so the splash still shows *something* rather than
         nothing if both of the above somehow fail."""
    # 1. Optional on-disk override.
    if image_name:
        pix = QtGui.QPixmap(_resource_path(image_name))
        if not pix.isNull():
            return pix

    # 2. Embedded image (the normal path).
    pix = _embedded_pixmap()
    if not pix.isNull():
        return pix

    # 3. Last-resort text card.
    pix = QtGui.QPixmap(480, 240)
    pix.fill(QtGui.QColor("#141414"))
    painter = QtGui.QPainter(pix)
    painter.setPen(QtCore.Qt.GlobalColor.white)
    painter.setFont(QtGui.QFont("Arial", 16))
    painter.drawText(pix.rect(), QtCore.Qt.AlignmentFlag.AlignCenter, fallback_text)
    painter.end()
    return pix


def show_splash(app,
                image_name: str = "",
                seconds: float = 3.0,
                fallback_text: str = "Loading...") -> None:
    """Show a centered, frameless, always-on-top splash for `seconds`, then close.

    Parameters
    ----------
    app : QApplication
        The application instance (already created by the caller).
    image_name : str
        Optional path to an on-disk image that overrides the embedded splash.
        Leave empty ("") to use the embedded image (the normal case).
    seconds : float
        How long the splash stays fully visible.
    fallback_text : str
        Text shown if no image (embedded or on-disk) can be loaded.

    Notes
    -----
    This is deliberately blocking: it returns only after the splash has been up
    for the full `seconds`. But it keeps the Qt event loop alive during the wait
    (via processEvents), so the image paints and stays on screen the whole time
    -- unlike a bare time.sleep(), which freezes the paint and makes the splash
    just flash. Any failure here is swallowed so the app still starts.
    """
    try:
        pix = _load_pixmap(image_name, fallback_text)

        label = QtWidgets.QLabel()
        label.setPixmap(pix)
        label.setWindowFlags(
            QtCore.Qt.WindowType.FramelessWindowHint
            | QtCore.Qt.WindowType.WindowStaysOnTopHint
            | QtCore.Qt.WindowType.SplashScreen
        )
        label.setAttribute(QtCore.Qt.WidgetAttribute.WA_TranslucentBackground)
        label.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        label.setFixedSize(pix.size())

        # Center on the primary screen.
        screen = QtWidgets.QApplication.primaryScreen().availableGeometry()
        label.move(
            (screen.width() - pix.width()) // 2,
            (screen.height() - pix.height()) // 2,
        )

        label.show()
        label.raise_()
        label.activateWindow()

        # Keep the splash painted and responsive for the full duration. We pump
        # the event loop in small slices instead of sleeping through it.
        deadline = time.monotonic() + max(0.0, seconds)
        while time.monotonic() < deadline:
            app.processEvents(QtCore.QEventLoop.ProcessEventsFlag.AllEvents, 30)
            time.sleep(0.01)

        label.close()
        app.processEvents()
    except Exception as exc:
        # A splash is cosmetic; never let it stop the app from launching.
        print(f"[splash] skipped: {exc}")


if __name__ == "__main__":
    # Standalone smoke test: shows the embedded splash for 3s, then exits.
    _app = QtWidgets.QApplication(sys.argv)
    show_splash(_app, seconds=3.0)


